pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GSPFunding} from "../src/GSPFunding.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(uint256 amount) internal {
        vm.assume(amount > 0);
        uint256 balBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        vm.assume(amount > balBefore);
        bool reverted;
        try c.transfer(address(0xdead), amount) { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted && c.balanceOf(address(this)) == balBefore && c.totalSupply() == supplyBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
